-- ── verification (this part) ─────────────────────────────────────────────
do $verify$
declare v_tables int;
begin
  select count(*) into v_tables from pg_tables where schemaname = 'public' and tablename like 'ref\_khld\_%';
  if v_tables <> 237 then
    raise exception '0141: expected 237 ref_khld_ tables, found %', v_tables;
  end if;
end $verify$;
